-- Required initial print size and paper mapping.
-- Safe to re-run. Existing rows and owner-entered pricing are never overwritten.






-- Mirror legacy mappings into the owner pricing table without overwriting edits.
SELECT size_id, material_id,
  CASE WHEN size_id='20000000-0000-4000-8000-000000000001'
    AND material_id IN ('30000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000004')
    THEN 0.10 ELSE 0 END,
  FALSE, TRUE, 0 FROM material_sizes;
